151	template <typename KeyGetter, bool is_asof_join>
152	KeyGetter HashJoinMethods<KIND, STRICTNESS, MapsTemplate>::createKeyGetter(const ColumnRawPtrs & key_columns, const Sizes & key_sizes, HashJoin::RightTableData::KeyRange key_range)
153	{
154	    KeyGetter getter = [&]()
155	    {
156	        if constexpr (is_asof_join)
157	        {
158	            auto key_column_copy = key_columns;
159	            auto key_size_copy = key_sizes;
160	            key_column_copy.pop_back();
161	            key_size_copy.pop_back();
162	            return KeyGetter(key_column_copy, key_size_copy, nullptr);
163	        }
164	        else
165	            return KeyGetter(key_columns, key_sizes, nullptr);
166	    }();
167	
168	    if constexpr (ColumnsHashing::IsHashMethodInRange<KeyGetter>::value)
169	    {
170	        getter.min_key = static_cast<decltype(getter.min_key)>(key_range.min_key);
171	        getter.range_size = static_cast<decltype(getter.range_size)>(key_range.size);
172	    }
173	
174	    return getter;
175	}
